```javascript
function getUserData() {
  fetch('https://api.example.com/user')
    .then(response => {
      if (!response.ok) {
        throw new Error('Network response was not ok');
      }
      return response.json();
    })
    .then(data => {
      console.log(data.name);
    })
    .catch(error => {
      console.error('Fetch error:', error);
    });
}
```

